fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());

    for s in a {
        let bytes = s.as_bytes();
        let len = bytes.len();
        let mut lines = Vec::new();
        let mut start = 0;
        let mut i = 0;

        while i < len {
            let c = bytes[i];
            if c == b'\r' || c == b'\n' {
                // Determine length of the line ending (\r, \n or \r\n)
                let newline_len = if c == b'\r' && i + 1 < len && bytes[i + 1] == b'\n' {
                    2
                } else {
                    1
                };

                // Decide where this line should end
                let end = if keepends {
                    i + newline_len
                } else {
                    i
                };

                // Push the substring for this line
                lines.push(s[start..end].to_string());

                // Skip over the newline characters
                i += newline_len;
                start = i;
            } else {
                i += 1;
            }
        }

        // Any leftover text after the last newline
        if start < len {
            lines.push(s[start..len].to_string());
        } else if s.is_empty() {
            // Ensure non-empty inner list for empty input string
            lines.push(String::new());
        }

        result.push(lines);
    }

    result
}

#[cfg(test)]
mod tests {
    use super::splitlines;

    #[test]
    fn test_basic() {
        let input = vec![
            "Hello\nWorld".to_string(),
            "".to_string(),
            "Foo\r\nBar\rBaz".to_string(),
            "\nLeading newline".to_string(),
            "Trailing newline\n".to_string(),
        ];

        // keepends = false
        let out = splitlines(input.clone(), false);
        assert_eq!(out.len(), input.len());
        assert_eq!(out[0], vec!["Hello".to_string(), "World".to_string()]);
        assert_eq!(out[1], vec!["".to_string()]); // non-empty inner vec
        assert_eq!(out[2], vec!["Foo".to_string(), "Bar".to_string(), "Baz".to_string()]);
        assert_eq!(out[3], vec!["".to_string(), "Leading newline".to_string()]);
        assert_eq!(out[4], vec!["Trailing newline".to_string()]);

        // keepends = true
        let out = splitlines(input, true);
        assert_eq!(out[0], vec!["Hello\n".to_string(), "World".to_string()]);
        assert_eq!(out[1], vec!["".to_string()]);
        assert_eq!(
            out[2],
            vec!["Foo\r\n".to_string(), "Bar\r".to_string(), "Baz".to_string()]
        );
        assert_eq!(out[3], vec!["\n".to_string(), "Leading newline".to_string()]);
        assert_eq!(out[4], vec!["Trailing newline\n".to_string()]);
    }
}